43|function runCommand(command, args, label, timeoutMs = 300000) {
44|  // Validate command is allowed
45|  const allowedCommands = ['uv', 'node', 'python3', 'yt-dlp', 'ffmpeg', 'ffprobe'];
46|  const cmdName = path.basename(command).replace(/\.exe$/i, '');
